add_to_cart_by_channel:
mutation addToCartByChannel($cartId: String!, $productId: String!, $quantity: Long!, $version: Long!, $locale: Locale!) {
  updateMyCart(
    id: $cartId
    actions: {addLineItem: {productId: $productId, quantity: $quantity, custom: {typeKey: "line-item-custom-fields"}}}
    version: $version
  ) {
    id
    isAbleToCheckout
    isRestricted
    isHazardous
    isEmpty
    isDangerous
    version
    isSplit
    splittableSupplyChannelKeys
    totalLineItemQuantity
    discountedPrice {
      centAmount
      currencyCode
      fractionDigits
    }
    totalPrice {
      centAmount
      currencyCode
      fractionDigits
    }
    shipping {
      ...defaultShipping
    }
    lineItems {
      ...defaultLineItem
    }
  }
}

fragment defaultShipping on Shipping {
  shippingKey
