    id
    version
    name
  }
  totalPrice {
    centAmount
    currencyCode
    fractionDigits
  }
  preDiscountedPrice {
    centAmount
    currencyCode
    fractionDigits
  }
  shippingDetails {
    targets {
      addressKey
      shippingMethodKey
      quantity
    }
    valid
  }
  productKey
  quantity
