set_shipping_address:
mutation setShippingAddress($action: SetCartShippingAddress!, $locale: Locale!, $preferredLocale: Locale) {
  setShippingAddress(action: $action) {
    ...CartFragment
    __typename
  }
}

fragment CartFragment on Cart {
  id
  country
  customerId
  customerEmail
  lineItems {
    ...LineItemFragment_Cart
    __typename
  }
  shippingAddress {
    ...AddressFragment
    __typename
  }
  billingAddress {
    ...AddressFragment
    __typename
  }
  shippingInfo {
    shippingMethod {
      id
      key
      name
      __typename
    }
    price {
      ...MoneyFragment
      __typename
    }
    taxedPrice {
      totalNet {
        ...MoneyFragment
        __typename
      }
      totalGross {
        ...MoneyFragment
        __typename
      }
      __typename
    }
    taxRate {
      includedInPrice
      __typename
    }
    discountedPrice {
      value {
        ... on Money {
          ...MoneyFragment
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
  totalPrice {
    ...MoneyFragment
    __typename
  }
  taxedPrice {
    totalNet {
      ...MoneyFragment
      __typename
    }
    totalGross {
      ...MoneyFragment
      __typename
    }
    __typename
  }
  discountCodes {
    ...DiscountCodeFragment
    __typename
  }
  discountOnTotalPrice {
    includedDiscounts {
      discount {
        id
        description(locale: $locale)
        fallbackDescription: description(locale: en)
        name(locale: $locale)
        fallbackName: name(locale: en)
        requiresDiscountCode
        __typename
      }
      discountedAmount {
        ...MoneyFragment
        __typename
      }
      __typename
    }
    __typename
  }
  __typename
}

fragment MoneyFragment on Money {
  currencyCode
  centAmount
  fractionDigits
  __typename
}

fragment LineItemFragment_Cart on LineItem {
  id
  productSlug(locale: $locale)
  fallbackSlug: productSlug(locale: en)
  preferredSlug: productSlug(locale: $preferredLocale)
  lineItemMode
  name(locale: $locale)
  displayBrand
  displayName(locale: $locale)
  quantity
  productId
  productType {
    name
    __typename
  }
  category(locale: $locale)
  price {
    ...ProductPriceFragment
    __typename
  }
  mainImage {
    ...ImageAssetFragment
    __typename
  }
  variant {
    availability {
      noChannel {
        availableQuantity
        expectedDelivery
        __typename
      }
      __typename
    }
    brands {
      name
      value
      __typename
    }
    campaignId
    campaignSlug
    color(locale: $locale)
    gender {
      name
      value
      __typename
    }
    masterScale(locale: $locale)
    size
    sku
    key
    __typename
  }
  totalPrice {
    ...MoneyFragment
    __typename
  }
  taxedPrice {
    totalNet {
      ...MoneyFragment
      __typename
    }
    totalGross {
      ...MoneyFragment
      __typename
    }
    __typename
  }
  taxRate {
    includedInPrice
    __typename
  }
  discountedPricePerQuantity {
    ...DiscountedLineItemPriceForQuantityFragment
    __typename
  }
  __typename
}

fragment ProductPriceFragment on ProductPrice {
  id
  value {
    ...MoneyFragment
    __typename
  }
  country
  discounted {
    value {
      ...MoneyFragment
      __typename
    }
    discount {
      name(locale: $locale)
      description(locale: $locale)
      __typename
    }
    __typename
  }
  custom {
    customFieldsRaw {
      name
      value
      __typename
    }
    __typename
  }
  __typename
}

fragment DiscountedLineItemPriceForQuantityFragment on DiscountedLineItemPriceForQuantity {
  quantity
  discountedPrice {
    includedDiscounts {
      discount {
        id
        description(locale: $locale)
        fallbackDescription: description(locale: en)
        name(locale: $locale)
        fallbackName: name(locale: en)
        requiresDiscountCode
        __typename
      }
      discountedAmount {
        ...MoneyFragment
        __typename
      }
      __typename
    }
    __typename
  }
  __typename
}

fragment ImageAssetFragment on ImageAsset {
  alt
  aspectRatio
  base64
  bgColor
  height
  id
  sizes
  src
  srcSet
  credits {
    collection
    companyName
    licenseHolder
    photographerUrl
    photographerName
    __typename
  }
  title
  width
  focalPoint {
    id
    x
    y
    __typename
  }
  __typename
}

fragment AddressFragment on Address {
  firstName
  lastName
  streetName
  postalCode
  city
  region
  country
  phone
  additionalAddressInfo
  __typename
}

fragment DiscountCodeFragment on DiscountCodeInfo {
  state
  discountCode {
    id
    code
    name(locale: $locale)
    description(locale: $locale)
    __typename
  }
  __typename
}

